css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .mast { position: absolute; left: 45%; bottom: 6%; width: 10%; height: 34%; border-radius: 3px; background: linear-gradient(90deg, #cbd5e1, #475569); }
.loader .dish { position: absolute; left: 22%; top: 26%; width: 56%; height: 42%; border-radius: 50%; background: radial-gradient(ellipse at 46% 40%, color-mix(in srgb, #fff 32%, var(--accent)), var(--accent)); transform-origin: 50% 100%; animation: dish-sweep calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .dish::after { content: ''; position: absolute; left: 44%; top: 34%; width: 12%; height: 42%; border-radius: 3px; background: #475569; }
.loader span { position: absolute; left: 50%; top: 30%; border-radius: 50%; border: 3px solid var(--accent-2); border-bottom-color: transparent; border-left-color: transparent; opacity: 0; animation: dish-wave calc(var(--loader-speed) * 1.8) ease-out infinite; }
.loader span:nth-of-type(1) { width: 22%; height: 22%; margin: -11% 0 0 -11%; }
.loader span:nth-of-type(2) { width: 40%; height: 40%; margin: -20% 0 0 -20%; animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-of-type(3) { width: 58%; height: 58%; margin: -29% 0 0 -29%; animation-delay: calc(var(--loader-speed) * 1.2); }
@keyframes dish-sweep { 0%, 100% { transform: rotate(-24deg); } 50% { transform: rotate(24deg); } }
@keyframes dish-wave { 0% { opacity: 0; transform: rotate(-45deg) scale(.5); } 25% { opacity: .95; } 100% { opacity: 0; transform: rotate(-45deg) scale(1.25); } }
